<section class="portal-card"><h2>{{ $county?'ارتباط با فرمانداری شهرستان '.$county['name']:'ارتباط با استانداری مازندران' }}</h2><form class="portal-form" x-data="apiForm('contact')" @submit.prevent="submit($event)"><fieldset :disabled="busy">@if($county)<input type="hidden" name="county_slug" value="{{ $county['slug'] }}">@endif<label>نام و نام خانوادگی<input name="name" autocomplete="name" required maxlength="120"></label><label>ایمیل<input type="email" name="email" autocomplete="email" required dir="ltr"></label><label>تلفن — اختیاری<input type="tel" name="phone" autocomplete="tel" dir="ltr"></label><label>موضوع<input name="subject" required maxlength="255"></label><label>متن پیام<textarea name="body" required minlength="10" maxlength="10000" rows="8"></textarea></label><button class="portal-button">ارسال پیام</button></fieldset><p role="alert" x-text="error"></p><p role="status" x-text="message"></p></form></section>
